<?php
if (!defined('ABSPATH')) exit;
$kind = isset($_GET['kind']) && is_string($_GET['kind']) ? sanitize_title(wp_unslash($_GET['kind'])) : '';
if ($kind && !get_term_by('slug', $kind, 'fave_kind')) $kind = '';
$terms = get_terms(array('taxonomy' => 'fave_kind', 'hide_empty' => true));
$labels = array('life-style' => '生活器物', 'personal' => '随身之物', 'workspace' => '工作与阅读', 'gear' => '出行装备');
$fave_page = isset($_GET['faves_page']) && is_scalar($_GET['faves_page']) ? max(1, absint($_GET['faves_page'])) : 1;
$args = array('post_type' => 'journal_fave', 'post_status' => 'publish', 'posts_per_page' => 24, 'paged' => $fave_page, 'orderby' => 'date', 'order' => 'DESC');
if ($kind) $args['tax_query'] = array(array('taxonomy' => 'fave_kind', 'field' => 'slug', 'terms' => $kind));
$items = new WP_Query($args);
$base = fieldnotes_boughs_url('minimalism');
?>
<section class="boughs-keepsakes" aria-labelledby="boughs-keepsakes-title">
    <?php $keepsakes_page = fieldnotes_section_page('faves'); if ($keepsakes_page && !post_password_required($keepsakes_page) && trim($keepsakes_page->post_content)) : ?><div class="boughs-custom-copy"><?php echo apply_filters('the_content', $keepsakes_page->post_content); ?></div><?php endif; ?>
    <div class="boughs-section-heading"><div><h2 id="boughs-keepsakes-title">留在日常</h2><p>一些反复使用，也愿意认真介绍的小选择。</p></div><span><?php echo esc_html(number_format_i18n($items->found_posts)); ?> 件日常之选</span></div>
    <form class="fn-keepsakes-search" action="https://search.jd.com/Search" method="get" target="_blank" rel="noopener noreferrer"><label for="fn-keepsakes-keyword">把想找的物品，交给京东。</label><div><input id="fn-keepsakes-keyword" name="keyword" type="search" placeholder="物品、品牌，或一个具体的名字" maxlength="100" required><input type="hidden" name="enc" value="utf-8"><button type="submit">去京东寻找 <span aria-hidden="true">↗</span></button></div></form>
    <div class="fn-keepsakes-selection" hidden><label><input type="checkbox" class="fn-keepsakes-select-page">选择此页</label><p class="fn-keepsakes-selection-count" role="status">尚未选择</p><button type="button" class="fn-keepsakes-clear">清空</button><button type="button" class="fn-keepsakes-review" disabled>查看选购清单 <span aria-hidden="true">↗</span></button></div>
    <nav class="boughs-fave-filters" aria-label="日常选择分类"><a href="<?php echo esc_url($base); ?>"<?php echo $kind === '' ? ' aria-current="page"' : ''; ?>>全部</a><?php if (!is_wp_error($terms)) foreach ($terms as $item) : ?><a href="<?php echo esc_url(add_query_arg('kind', $item->slug, $base)); ?>"<?php echo $kind === $item->slug ? ' aria-current="page"' : ''; ?>><?php echo esc_html($labels[$item->slug] ?? $item->name); ?></a><?php endforeach; ?></nav>
    <?php if ($items->have_posts()) : ?><div class="faves-grid"><?php while ($items->have_posts()) : $items->the_post(); $kinds = get_the_terms(get_the_ID(), 'fave_kind'); $slug = !is_wp_error($kinds) && !empty($kinds) ? $kinds[0]->slug : ''; $product = fieldnotes_keepsake_product(get_the_ID()); ?>
        <article class="fave-card" data-keepsake="<?php echo esc_attr(wp_json_encode($product)); ?>"><div class="fave-card-image"><?php if (has_post_thumbnail()) : the_post_thumbnail('medium_large'); else : ?><img src="<?php echo esc_url(fieldnotes_fave_image(get_the_ID())); ?>" alt="" loading="lazy" width="800" height="600"><?php endif; ?><label class="fn-keepsake-choose" hidden><input type="checkbox" value="<?php echo esc_attr((string) get_the_ID()); ?>"><span class="screen-reader-text">选择 <?php the_title(); ?></span></label></div><div class="fave-card-copy"><p class="fave-card-kind"><?php echo esc_html($labels[$slug] ?? '日常之选'); ?></p><h3><?php the_title(); ?></h3><p class="fave-card-description"><?php echo esc_html(wp_trim_words(get_the_excerpt(), 32, '…')); ?></p><a class="fn-keepsake-jd" href="<?php echo esc_url($product['url']); ?>" target="_blank" rel="noopener noreferrer"><?php echo $product['sku'] ? '在京东查看' : '在京东寻找'; ?> <span aria-hidden="true">↗</span></a></div></article>
    <?php endwhile; ?></div><?php echo wp_kses_post(paginate_links(array('base' => add_query_arg('faves_page', '%#%', $kind ? add_query_arg('kind', $kind, $base) : $base), 'format' => '', 'current' => $fave_page, 'total' => $items->max_num_pages, 'prev_text' => '上一页', 'next_text' => '下一页'))); ?>
    <?php else : ?><p class="boughs-empty">慢慢收集，值得长久相伴的小物。</p><?php endif; wp_reset_postdata(); ?>
    <dialog class="fn-keepsakes-dialog" aria-labelledby="fn-keepsakes-dialog-title" aria-describedby="fn-keepsakes-dialog-copy"><div class="fn-keepsakes-dialog-heading"><h2 id="fn-keepsakes-dialog-title">选购清单</h2><button type="button" class="fn-keepsakes-close" aria-label="关闭选购清单">×</button></div><p id="fn-keepsakes-dialog-copy">按清单在京东确认款式并加入购物车，随后统一结算。</p><ul class="fn-keepsakes-list"></ul><p class="fn-keepsakes-list-status" role="status"></p><div class="fn-keepsakes-dialog-actions"><button type="button" class="fn-keepsakes-copy">复制清单</button><a href="https://cart.jd.com/cart.action" target="_blank" rel="noopener noreferrer">去京东购物车结算 <span aria-hidden="true">↗</span></a></div><p class="fn-keepsakes-footnote">清单仅存于此标签页。价格、库存及加购结果，请以京东页面为准。</p></dialog>
</section>
<?php if ($boughs_term && (int) $boughs_term->count > 0) fieldnotes_boughs_collection_posts($boughs_term, '使用与取舍'); ?>
